SELECT TABLE_NAME AS 'Tabla Creada', TABLE_COMMENT AS 'Descripción'
FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_SCHEMA = 'erp_little_horizons'
ORDER BY TABLE_NAME;

SELECT tabla AS 'Tabla', total AS 'Registros' FROM (
                                                       SELECT 'grados' AS tabla, COUNT(*) AS total FROM grados
                                                       UNION ALL
                                                       SELECT 'estudiantes' AS tabla, COUNT(*) AS total FROM estudiantes
                                                       UNION ALL
                                                       SELECT 'acudientes' AS tabla, COUNT(*) AS total FROM acudientes
                                                       UNION ALL
                                                       SELECT 'estudiante_acudiente' AS tabla, COUNT(*) AS total FROM estudiante_acudiente
                                                       UNION ALL
                                                       SELECT 'matriculas' AS tabla, COUNT(*) AS total FROM matriculas
                                                       UNION ALL
                                                       SELECT 'materias' AS tabla, COUNT(*) AS total FROM materias
                                                       UNION ALL
                                                       SELECT 'profesores' AS tabla, COUNT(*) AS total FROM profesores
                                                       UNION ALL
                                                       SELECT 'asignaciones_profesor' AS tabla, COUNT(*) AS total FROM asignaciones_profesor
                                                       UNION ALL
                                                       SELECT 'horarios_clase' AS tabla, COUNT(*) AS total FROM horarios_clase
                                                       UNION ALL
                                                       SELECT 'inscripciones_materia' AS tabla, COUNT(*) AS total FROM inscripciones_materia
                                                       UNION ALL
                                                       SELECT 'registros_academicos' AS tabla, COUNT(*) AS total FROM registros_academicos
                                                       UNION ALL
                                                       SELECT 'asistencias' AS tabla, COUNT(*) AS total FROM asistencias
                                                       UNION ALL
                                                       SELECT 'clubes' AS tabla, COUNT(*) AS total FROM clubes
                                                       UNION ALL
                                                       SELECT 'membresias_club' AS tabla, COUNT(*) AS total FROM membresias_club
                                                       UNION ALL
                                                       SELECT 'eventos' AS tabla, COUNT(*) AS total FROM eventos
                                                       UNION ALL
                                                       SELECT 'participantes_evento' AS tabla, COUNT(*) AS total FROM participantes_evento
                                                       UNION ALL
                                                       SELECT 'conceptos_pago' AS tabla, COUNT(*) AS total FROM conceptos_pago
                                                       UNION ALL
                                                       SELECT 'valores_personalizados' AS tabla, COUNT(*) AS total FROM valores_personalizados
                                                       UNION ALL
                                                       SELECT 'pagos' AS tabla, COUNT(*) AS total FROM pagos
                                                       UNION ALL
                                                       SELECT 'facturas' AS tabla, COUNT(*) AS total FROM facturas
                                                       UNION ALL
                                                       SELECT 'categorias_recurso' AS tabla, COUNT(*) AS total FROM categorias_recurso
                                                       UNION ALL
                                                       SELECT 'recursos' AS tabla, COUNT(*) AS total FROM recursos
                                                       UNION ALL
                                                       SELECT 'prestamos_estudiante' AS tabla, COUNT(*) AS total FROM prestamos_estudiante
                                                       UNION ALL
